76	      // List all files
77	      List<StoragePathInfo> entryList = metaClient.getStorage().globEntries(
78	          new StoragePath(metaClient.getArchivePath(), ".commits_.archive*"));
79	
80	      // Sort files by version suffix in reverse (implies reverse chronological order)
81	      entryList.sort(new ArchiveFileVersionComparator());
82	
83	      for (StoragePathInfo fs : entryList) {
84	        // Read the archived file
85	        try (HoodieLogFormat.Reader reader = HoodieLogFormat.newReader(metaClient.getStorage(),
