104	                    });
105	              }
106	            }
107	          }
108	
109	          if (filter != null) {
110	            int instantsInCurrentFile = instantsInRange.size() - instantsInPreviousFile;
111	            if (instantsInPreviousFile > 0 && instantsInCurrentFile == 0) {
112	              // Note that this is an optimization to skip reading unnecessary archived files
113	              // This signals we crossed lower bound of desired time window.
114	              break;
115	            }
116	          }
117	        } catch (Exception originalException) {
118	          // merge small archive files may left uncompleted archive file which will cause exception.
119	          // need to ignore this kind of exception here.
