90	  private void prepareLegacyArchivedTimeline(HoodieTableMetaClient metaClient) throws Exception {
91	    HoodieTestTable testTable = HoodieTestTable.of(metaClient);
92	    for (int i = 1; i < 11; i++) {
93	      String instantTime = String.format("%08d", i);
94	      HoodieCommitMetadata metadata = testTable.createCommitMetadata(instantTime, WriteOperationType.INSERT, Arrays.asList("par1", "par2"), 10, false);
95	      testTable.addCommit(instantTime, Option.of(metadata));
96	    }
97	    List<HoodieInstant> instants = TIMELINE_FACTORY.createActiveTimeline(metaClient, false).getInstantsAsStream().sorted().collect(Collectors.toList());
98	    // archive 2 times to have 2 log files.
99	    archive(metaClient, instants.subList(0, instants.size() / 2));
100	    archive(metaClient, instants.subList(instants.size() / 2, instants.size()));
101	  }
