103	  private HoodieLogFormat.Writer openWriter(HoodieTableMetaClient metaClient) {
104	    try {
105	      return HoodieLogFormat.newWriterBuilder()
106	          .onParentPath(metaClient.getArchivePath())
107	          .withFileId("commits").withFileExtension(HoodieArchivedLogFile.ARCHIVE_EXTENSION)
108	          .withStorage(metaClient.getStorage()).withInstantTime("").build();
109	    } catch (IOException e) {
110	      throw new HoodieException("Unable to initialize HoodieLogFormat writer", e);
111	    }
112	  }
113	
114	  public void archive(HoodieTableMetaClient metaClient, List<HoodieInstant> instants) throws HoodieCommitException {
115	    try (HoodieLogFormat.Writer writer = openWriter(metaClient)) {
116	      Schema wrapperSchema = HoodieArchivedMetaEntry.getClassSchema();
117	      LOG.info("Wrapper schema " + wrapperSchema.toString());
118	      List<IndexedRecord> records = new ArrayList<>();
119	      for (HoodieInstant hoodieInstant : instants) {
120	        try {
121	          records.add(convertToAvroRecord(hoodieInstant, metaClient));
122	        } catch (Exception e) {
123	          LOG.error("Failed to archive commits, .commit file: " + INSTANT_FILE_NAME_GENERATOR.getFileName(hoodieInstant), e);
124	          throw e;
125	        }
126	      }
127	      writeToFile(metaClient, wrapperSchema, records, writer);
128	    } catch (Exception e) {
129	      throw new HoodieCommitException("Failed to archive commits", e);
130	    }
131	  }
132	
133	  private void writeToFile(HoodieTableMetaClient metaClient, Schema wrapperSchema, List<IndexedRecord> records, HoodieLogFormat.Writer writer) throws Exception {
134	    if (records.size() > 0) {
135	      Map<HoodieLogBlock.HeaderMetadataType, String> header = new HashMap<>();
136	      header.put(HoodieLogBlock.HeaderMetadataType.SCHEMA, wrapperSchema.toString());
137	      final String keyField = metaClient.getTableConfig().getRecordKeyFieldProp();
138	      List<HoodieRecord> indexRecords = records.stream().map(HoodieAvroIndexedRecord::new).collect(Collectors.toList());
139	      HoodieAvroDataBlock block = new HoodieAvroDataBlock(indexRecords, header, keyField);
140	      writer.appendBlock(block);
141	      records.clear();
142	    }
143	  }
144	
145	  private IndexedRecord convertToAvroRecord(HoodieInstant hoodieInstant, HoodieTableMetaClient metaClient)
146	      throws IOException {
147	    return MetadataConversionUtils.createMetaWrapper(hoodieInstant, metaClient);
148	  }
