60	    Option<byte[]> instantDetails = metaClient.getActiveTimeline().getInstantDetails(hoodieInstant);
61	    if (hoodieInstant.isCompleted() && instantDetails.get().length == 0) {
62	      // in local FS and HDFS, there could be empty completed instants due to crash.
63	      // let's add an entry to the archival, even if not for the plan.
64	      return createMetaWrapperForEmptyInstant(hoodieInstant);
