66	    HoodieArchivedMetaEntry archivedMetaWrapper = new HoodieArchivedMetaEntry();
67	    archivedMetaWrapper.setCommitTime(hoodieInstant.requestedTime());
68	    archivedMetaWrapper.setActionState(hoodieInstant.getState().name());
69	    archivedMetaWrapper.setStateTransitionTime(hoodieInstant.getCompletionTime());
70	    switch (hoodieInstant.getAction()) {
71	      case HoodieTimeline.CLEAN_ACTION: {
72	        if (hoodieInstant.isCompleted()) {
73	          archivedMetaWrapper.setHoodieCleanMetadata(CleanerUtils.getCleanerMetadata(metaClient, instantDetails.get()));
74	        } else {
75	          archivedMetaWrapper.setHoodieCleanerPlan(CleanerUtils.getCleanerPlan(metaClient, instantDetails.get()));
76	        }
77	        archivedMetaWrapper.setActionType(ActionType.clean.name());
78	        break;
79	      }
80	      case HoodieTimeline.COMMIT_ACTION: {
81	        HoodieCommitMetadata commitMetadata = metaClient.getCommitMetadataSerDe().deserialize(hoodieInstant, instantDetails.get(), HoodieCommitMetadata.class);
82	        archivedMetaWrapper.setHoodieCommitMetadata(convertCommitMetadata(commitMetadata));
83	        archivedMetaWrapper.setActionType(ActionType.commit.name());
84	        break;
85	      }
86	      case HoodieTimeline.DELTA_COMMIT_ACTION: {
87	        HoodieCommitMetadata deltaCommitMetadata = metaClient.getCommitMetadataSerDe().deserialize(hoodieInstant, instantDetails.get(), HoodieCommitMetadata.class);
88	        archivedMetaWrapper.setHoodieCommitMetadata(convertCommitMetadata(deltaCommitMetadata));
89	        archivedMetaWrapper.setActionType(ActionType.deltacommit.name());
90	        break;
91	      }
92	      case HoodieTimeline.REPLACE_COMMIT_ACTION:
93	      case HoodieTimeline.CLUSTERING_ACTION: {
94	        if (hoodieInstant.isCompleted()) {
95	          HoodieReplaceCommitMetadata replaceCommitMetadata = HoodieReplaceCommitMetadata.fromBytes(instantDetails.get(), HoodieReplaceCommitMetadata.class);
96	          archivedMetaWrapper.setHoodieReplaceCommitMetadata(convertReplaceCommitMetadataToAvro(replaceCommitMetadata));
97	        } else if (hoodieInstant.isInflight()) {
