51	                           @Nullable HoodieArchivedTimeline.TimeRangeFilter filter,
52	                           HoodieArchivedTimeline.LoadMode loadMode,
53	                           Function<GenericRecord, Boolean> commitsFilter,
54	                           BiConsumer<String, GenericRecord> recordConsumer) {
55	    try {
56	      // List all files
57	      List<String> fileNames = LSMTimeline.latestSnapshotManifest(metaClient, metaClient.getArchivePath()).getFileNames();
58	
59	      Schema readSchema = LSMTimeline.getReadSchema(loadMode);
60	      fileNames.stream()
61	          .filter(fileName -> filter == null || LSMTimeline.isFileInRange(filter, fileName))
62	          .parallel().forEach(fileName -> {
63	            // Read the archived file
64	            try (HoodieAvroFileReader reader = (HoodieAvroFileReader) HoodieIOFactory.getIOFactory(metaClient.getStorage())
65	                .getReaderFactory(HoodieRecord.HoodieRecordType.AVRO)
66	                .getFileReader(DEFAULT_HUDI_CONFIG_FOR_READER, new StoragePath(metaClient.getArchivePath(), fileName))) {
67	              try (ClosableIterator<IndexedRecord> iterator = reader.getIndexedRecordIterator(HoodieLSMTimelineInstant.getClassSchema(), readSchema)) {
68	                while (iterator.hasNext()) {
69	                  GenericRecord record = (GenericRecord) iterator.next();
70	                  String instantTime = record.get(INSTANT_TIME_ARCHIVED_META_FIELD).toString();
71	                  if ((filter == null || filter.isInRange(instantTime))
72	                      && commitsFilter.apply(record)) {
73	                    recordConsumer.accept(instantTime, record);
74	                  }
75	                }
76	              }
77	            } catch (IOException ioException) {
78	              throw new HoodieIOException("Error open file reader for path: "
79	                  + new StoragePath(metaClient.getArchivePath(), fileName));
80	            }
81	          });
82	    } catch (IOException e) {
83	      throw new HoodieIOException(
84	          "Could not load archived commit timeline from path " + metaClient.getArchivePath(), e);
85	    }
86	  }
